template:
use std::cell::{RefCell, RefMut};

struct Config {
    port: u16,
}

fn get_port_mut(c: &RefCell<Config>)
    -> RefMut<u16>
{
    let guard = c.⟦slot1⟧();
    RefMut::map(guard, |c| ⟦slot2⟧)
}

fn main() {
    let cfg = RefCell::new(Config { port: 8080 });
    *get_port_mut(&cfg) = 9090;
    println!("{}", cfg.borrow().port);
}

tests:
#[test]
fn mutates_port() {
    let cfg = RefCell::new(Config { port: 80 });
    *get_port_mut(&cfg) = 443;
    assert_eq!(cfg.borrow().port, 443);
}
